INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('dashun','大顺','["大顺","李顺"]',NULL,NULL,'cn','east_asia',1644,1,NULL,'year',1645,12,NULL,'month',19728,19751,'ochre',NULL,NULL,'李自成由陕北起义军中崛起，1643年以襄阳为中心称新顺王，同年占领西安。1644年在西安建立大顺，改元永昌，继而攻入北京；山海关战败后退回西安，翌年继续南撤。1645年李自成死于湖北，其死亡经过有异说，余部此后继续活动。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('daxi','大西','["大西","西"]',NULL,NULL,'cn','east_asia',1644,12,NULL,'month',1647,12,NULL,'month',19739,19775,'ochre',NULL,NULL,'张献忠在明末起义中自领军队，1643年占武昌、称大西王，次年入川并在成都称帝，国号大西、年号大顺。1647年张献忠在西充战死，孙可望、李定国等余部转入云贵，随后归附南明。');
INSERT INTO "dynasties" ("id","name","alt_names","ethnicity","feudal_rank","scope","region","start_year","start_month","start_day","start_confidence","end_year","end_month","end_day","end_confidence","start_abs","end_abs","color_token","parent_id","group_id","note") VALUES ('mingzheng','明郑','["大明","东宁","延平"]',NULL,NULL,'cn','east_asia',1661,6,NULL,'month',1683,10,NULL,'month',19937,20205,'ochre',NULL,NULL,'郑成功以东南沿海抗清军队为基础，1661年率军进入台湾，设承天府及天兴、万年二县，1662年迫使荷兰东印度公司退出。郑经继位后于1664年改东都为东宁，郑氏继续奉明朝永历正朔；1683年澎湖战败，郑克塽降清，明郑结束。');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('li-zicheng','李自成','dashun','[]',NULL,NULL,1606,9,NULL,'month',1645,5,NULL,'month','["皇帝","起义领袖"]','陕西米脂人，曾任驿卒，后参加明末起义，归高迎祥部。1636年高迎祥被俘后继称闯王；1638年战败退入商洛，随后转入河南，借灾荒中流民参加扩大军队。1641年攻取洛阳，1643年据襄阳并夺取西安，1644年建立大顺、进占北京，山海关败后西撤，1645年去世，其死因有异说。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/李自成"}]',NULL,NULL,'大顺皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zhang-xianzhong','张献忠','daxi','[]',NULL,NULL,1606,1,NULL,'year',1647,1,NULL,'year','["皇帝","起义领袖"]','陕西定边人，曾服兵役，1630年参加陕北起义，逐渐自领军队。1638年在谷城受明朝招安，次年再起；1643年攻取武昌，称大西王，随后入川，1644年在成都称帝，国号大西。清军入川后于1647年战死，余部继续活动。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/张献忠"}]',NULL,NULL,'大西皇帝','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-chenggong','郑成功','mingzheng','[]',NULL,NULL,1624,1,NULL,'year',1662,6,NULL,'month','["君主","军事家"]','郑芝龙之子，南明隆武帝赐姓朱、赐名成功。1646年清军入闽、父亲降清后，继续抗清，依靠厦门、金门及海上贸易组织军队。1659年攻南京失败后转向台湾，1661年渡海围攻荷兰据点，1662年迫使荷兰殖民者投降，建立台湾统治，同年去世。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑成功"},{"label":"《明史·郑成功传》（维基文库）","url":"https://zh.wikisource.org/wiki/明史/卷271"}]','武王',NULL,'延平王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-jing','郑经','mingzheng','[]',NULL,NULL,1642,10,NULL,'month',1681,3,NULL,'month','["君主"]','郑成功嫡长子，1662年嗣延平王，据台湾奉永历正朔；1681年卒。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑经"}]','文王',NULL,'延平王','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('zheng-keshuang','郑克塽','mingzheng','[]',NULL,NULL,1670,1,NULL,'year',1707,1,NULL,'year','["君主"]','郑经之子，1681年嗣延平王；1683年澎湖战败降清，明郑终结。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/郑克塽"}]',NULL,NULL,'延平王','[]');
